from pathlib import Path
import hashlib, json, re

root = Path('products/services/world-bank-buyer-acceptance')
raw = (root / 'raw/procurement-feed.json').read_bytes()
data = json.loads(raw)
notices = data.get('procnotices') if isinstance(data, dict) else None
pattern = re.compile(r'\b(data|migration|metadata|digitization|digitisation|documentation|quality assurance|records)\b', re.I)
leads = []
count = 0
if isinstance(notices, dict):
    for key, notice in notices.items():
        if not isinstance(notice, dict):
            continue
        count += 1
        fields = {name: notice[name] for name in ('id', 'notice_title', 'bid_description', 'notice_type', 'publication_date', 'submission_deadline', 'notice_url', 'url', 'project_id') if isinstance(notice.get(name), (str, int))}
        for name in ('notice_title', 'bid_description'):
            if isinstance(fields.get(name), str):
                fields[name] = fields[name][:400]
        text = ' '.join(str(fields.get(name, '')) for name in ('notice_title', 'bid_description'))
        if pattern.search(text):
            leads.append({'feed_key': key, 'fields_as_published': fields})
result = {'source_sha256': hashlib.sha256(raw).hexdigest(), 'feed_shape': sorted(data) if isinstance(data, dict) else type(data).__name__, 'procnotices_type': type(notices).__name__, 'notice_objects_screened': count, 'keyword_leads': leads, 'scope': 'Captured page only. Keyword leads do not establish open status, separately quotable scope, eligibility, or an authorized response route.'}
(root / 'director-feed-leads.json').write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
